INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine höhere Abtastrate immer bessere Ergebnisse liefert?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Signal und Speicher"}, {"text": "Ja", "correct": false, "because": "Kann unnötige Daten erzeugen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Theorem definiert die Mindestabtastrate für ein Signal?', 3, '[{"text": "Nyquist-Shannon-Theorem", "correct": true, "because": "Fordert doppelte Signalbandbreite"}, {"text": "Fourier-Theorem", "correct": false, "because": "Für Frequenzanalyse"}, {"text": "Bayes-Theorem", "correct": false, "because": "Für Statistik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Qualität einer Abtastung?', 5, '[{"text": "Abtastrate", "correct": true, "because": "Bestimmt Detailgenauigkeit"}, {"text": "Signalbandbreite", "correct": true, "because": "Grenzt Frequenzbereich ein"}, {"text": "Farbtiefe", "correct": false, "because": "Nur für Bilder"}, {"text": "Speicherkapazität", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aliasing tritt bei zu niedriger Abtastrate auf. b) Es verbessert die Signalqualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Aliasing verschlechtert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Abtastrate?', 4, '[{"text": "Signalbandbreite", "correct": false, "because": "Bestimmt Mindestrate"}, {"text": "Anwendungszweck", "correct": false, "because": "Beeinflusst Anforderungen"}, {"text": "Signalton", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Abtastrate von 44,1 kHz für Audio üblich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für CDs"}, {"text": "Nein", "correct": false, "because": "44,1 kHz ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik verhindert Aliasing bei der Signalabtastung?', 4, '[{"text": "Tiefpassfilter", "correct": true, "because": "Schneidet hohe Frequenzen"}, {"text": "Hochpassfilter", "correct": false, "because": "Lässt hohe Frequenzen durch"}, {"text": "Kompression", "correct": false, "because": "Reduziert Daten, nicht Aliasing"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Abtastung nur für Audio relevant ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Video, Sensoren"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Abtastrate immer konstant?', 2, '[{"text": "Nein", "correct": true, "because": "Kann adaptiv sein"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Parameter sind bei der statistischen Datenabtastung wichtig?', 5, '[{"text": "Stichprobengröße", "correct": true, "because": "Beeinflusst Genauigkeit"}, {"text": "Zufälligkeit", "correct": true, "because": "Vermeidet Verzerrung"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Diagrammdesign", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abtastung eines Audiosignals?', 4, '[{"text": "Ausreichende Abtastrate", "correct": true, "because": "Sichert Qualität"}, {"text": "Minimale Rate", "correct": false, "because": "Risiko für Aliasing"}, {"text": "Signalstärke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nyquist-Rate ist doppelte Signalbandbreite. b) Sie garantiert perfekte Rekonstruktion.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, idealisierte Annahme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine präzise Signalabtastung?', 3, '[{"text": "Tiefpassfilter", "correct": false, "because": "Verhindert Aliasing"}, {"text": "Ausreichende Abtastrate", "correct": false, "because": "Sichert Genauigkeit"}, {"text": "Signalvisualisierung", "correct": true, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Aliasing vermeide?', 4, '[{"text": "Abtastrate über Nyquist setzen", "correct": true, "because": "Erfüllt Mindestanforderung"}, {"text": "Niedrige Rate wählen", "correct": false, "because": "Verursacht Aliasing"}, {"text": "Ohne Filter arbeiten", "correct": false, "because": "Erhöht Aliasing"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Abtastung immer digital ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Abtastung wandelt analog in digital"}, {"text": "Nein", "correct": false, "because": "Primär digitaler Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, repräsentative Daten in der Statistik zu erhalten?', 4, '[{"text": "Zufallsauswahl", "correct": true, "because": "Vermeidet Verzerrung"}, {"text": "Maximale Stichprobe", "correct": false, "because": "Nicht immer nötig"}, {"text": "Einheitliche Auswahl", "correct": false, "because": "Kann Verzerrung erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Abtastrate von 8 kHz für Sprache ausreichend?', 2, '[{"text": "Ja", "correct": true, "because": "Deckt Sprachbandbreite ab"}, {"text": "Nein", "correct": false, "because": "8 kHz ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine hohe Abtastrate?', 5, '[{"text": "Detailgenauigkeit", "correct": true, "because": "Mehr Datenpunkte"}, {"text": "Weniger Aliasing", "correct": true, "because": "Überschreitet Nyquist"}, {"text": "Geringer Speicherbedarf", "correct": false, "because": "Erhöht Bedarf"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Mehr Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der statistischen Datenabtastung unwichtig?', 3, '[{"text": "Stichprobengröße", "correct": false, "because": "Beeinflusst Genauigkeit"}, {"text": "Zufälligkeit", "correct": false, "because": "Sichert Repräsentativität"}, {"text": "Präsentationsstil", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Videosignal abtaste?', 4, '[{"text": "Hohe Abtastrate und Tiefpassfilter nutzen", "correct": true, "because": "Sichert Qualität"}, {"text": "Niedrige Rate wählen", "correct": false, "because": "Verursacht Artefakte"}, {"text": "Ohne Filter abtasten", "correct": false, "because": "Risiko für Aliasing"}]');
